void ne_cbus_attach ( struct device * parent , struct device * self , void * aux ) { struct ne_cbus_softc * csc = ( void * ) self ; struct ne2000_softc * nsc = & csc -> sc_ne2000 ; struct dp8390_softc * dsc = & nsc -> sc_dp8390 ; struct cbus_attach_args * caa = aux ; bus_space_tag_t nict = & ne_cbus_io_bst ; bus_space_handle_t nich ; bus_space_tag_t asict = nict ; bus_space_handle_t asich ; const char * typestr ; if ( bus_space_map ( nict , caa -> ca_iobase , NE2000_NPORTS , 0 , & nich ) ) { printf ( "%s: can't map i/o space\n" , dsc -> sc_dev . dv_xname ) ; return ; } if ( bus_space_subregion ( nict , nich , NE2000_ASIC_OFFSET , NE2000_ASIC_NPORTS , & asich ) ) { printf ( "%s: can't subregion i/o space\n" , dsc -> sc_dev . dv_xname ) ; return ; } dsc -> sc_regt = nict ; dsc -> sc_regh = nich ; nsc -> sc_asict = asict ; nsc -> sc_asich = asich ; nsc -> sc_type = ne2000_detect ( nsc ) ; switch ( nsc -> sc_type ) { case NE2000_TYPE_NE1000 : typestr = "NE1000" ; break ; case NE2000_TYPE_NE2000 : typestr = "NE2000" ; bus_space_write_1 ( nict , nich , ED_P0_CR , ED_CR_PAGE_0 | ED_CR_STP ) ; break ; default : printf ( ": where did the card go?!\n" ) ; return ; } printf ( ", %s" , typestr ) ; dsc -> sc_enabled = 1 ; ne2000_attach ( nsc , NULL ) ; if ( cbus_isrlink ( dp8390_intr , dsc , caa -> ca_int , IPL_NET , dsc -> sc_dev . dv_xname ) != 0 ) { printf ( ": couldn't establish interrupt handler\n" ) ; } } 